scwin.checkcombobox1_oncheckboxclick = function(index,isChecked,value) {
    if (value == "all") {
        for(var i=1;i<=14;i++) {
            if (i > 1) {
                grd_sample1.setColumnVisible("col" + i, isChecked);
            }
        }
    } else {
        if (index != "1") {
            grd_sample1.setColumnVisible("col" + index, isChecked);
        }
    }
};

scwin.checkVal = function() {
    let width = 1000;

    const element = WebSquare.wUnit.getDomById('grd_sample1_cell_0_3');
    if (element) {
        const computedStyle = window.getComputedStyle(element);
        // width 값 가져오기
        width = computedStyle.width;
        // 대소비교를 위해 정수형으로 변경
        width = Number(width.replace("px", ""));

        console.log('width 값 : ', width);
    } else {
        console.error('요소를 찾을 수 없습니다.');
    }

    return width < 300;
};

